{
"architectureObjects": [
{
"name": "Backend API Layer",
"type": "component",
"descriptionMarkdown": "Camada de API responsável por expor os serviços necessários à aplicação mobile City Pass. Deve concentrar os endpoints autenticados para login social, pagamentos, planos ativos, geração de cupons, validação de cupons e consulta de histórico. Deve manter uma separação clara entre controladores HTTP, serviços de domínio e acesso à base de dados."
},
{
"name": "Authentication Service",
"type": "service",
"descriptionMarkdown": "Serviço responsável por autenticação por e-mail, Google e Apple. Deve validar credenciais, receber tokens dos fornecedores externos, associar identidades sociais a utilizadores internos e emitir tokens de sessão para a aplicação mobile. Este serviço suporta FR-02, TC-02 e RNF-03."
},
{
"name": "Payment Service",
"type": "service",
"descriptionMarkdown": "Serviço responsável por iniciar pagamentos, guardar o estado do pagamento e confirmar se um plano pode ser ativado. Deve suportar métodos Cartão de Crédito, MB WAY e Apple Pay através de integração com gateway de pagamentos. Este serviço suporta FR-08 e RNF-04."
},
{
"name": "Plan Activation Service",
"type": "service",
"descriptionMarkdown": "Serviço responsável por criar e manter planos ativos após pagamento confirmado. Deve calcular data de início, data de fim, número de pessoas, desconto aplicável e estado do plano. Deve impedir geração de cupom quando não existir plano ativo válido."
},
{
"name": "Coupon Generation Service",
"type": "service",
"descriptionMarkdown": "Serviço responsável por gerar cupons digitais associados ao utilizador, ao plano ativo e ao restaurante escolhido. Deve gerar código alfanumérico único, payload para QR Code, validade e estado inicial do cupom. Este serviço suporta STK-04 e FR-09."
},
{
"name": "Coupon Validation Service",
"type": "service",
"descriptionMarkdown": "Serviço responsável por validar cupons por QR Code ou código manual. Deve confirmar autenticidade, validade temporal, estado do cupom, restaurante associado e existência de plano ativo. Após validação bem-sucedida, deve marcar o cupom como utilizado para impedir reutilização. Este serviço suporta STK-05, FR-11, FR-12 e RNF-06."
},
{
"name": "Coupon Anti-Fraud Rules",
"type": "policy",
"descriptionMarkdown": "Conjunto de regras para prevenir uso indevido de cupons. Deve impedir validações duplicadas, validar restaurante correto, rejeitar cupons expirados, rejeitar cupons de planos inativos e manter registo auditável de tentativas de validação."
},
{
"name": "History Query Service",
"type": "service",
"descriptionMarkdown": "Serviço responsável por disponibilizar o histórico de cupons utilizados, expirados e todos os registos relevantes para cliente e Grupo Ferreira. Embora a apresentação seja Frontend, o Backend deve fornecer dados filtráveis, paginados e consistentes."
},
{
"name": "Backend Security Boundary",
"type": "security",
"descriptionMarkdown": "Fronteira de segurança do Backend. Deve proteger dados pessoais, garantir autenticação nos endpoints privados, validar permissões por papel de utilizador, evitar exposição de dados sensíveis e centralizar logs de eventos críticos relacionados com autenticação, pagamentos e cupons."
}
],
