"method": "GET",
"path": "/api/payments/{paymentId}",
"description": "Consulta estado atual de pagamento."
},
{
"method": "POST",
"path": "/api/payments/webhook",
"description": "Recebe confirmação assíncrona do gateway de pagamentos e atualiza estado do pagamento e plano."
},
{
"method": "GET",
"path": "/api/me/plan",
"description": "Obtém plano ativo, dias restantes, número de pessoas e desconto disponível para o utilizador autenticado."
},
{
"method": "POST",
"path": "/api/coupons",
"description": "Gera cupom para restaurante selecionado, associado ao utilizador autenticado e ao plano ativo."
},
{
"method": "GET",
"path": "/api/coupons",
"description": "Lista cupons do utilizador com filtros por estado, incluindo todos, utilizados e expirados."
},
{
"method": "GET",
"path": "/api/coupons/{couponId}",
"description": "Obtém detalhe de cupom, incluindo código, payload de QR Code, restaurante, validade e estado."
},
{
"method": "POST",
"path": "/api/coupons/validate",
"description": "Valida cupom por QR Code ou código manual e devolve estado do cupom."
},
{
"method": "POST",
"path": "/api/coupons/{couponId}/consume",
"description": "Marca cupom como utilizado após validação bem-sucedida e impede reutilização."
},
{
"method": "GET",
"path": "/api/admin/coupon-validations",
"description": "Permite ao Grupo Ferreira consultar registos de validação para auditoria operacional."
}
],
"modules": [
{
"name": "Backend",
"submodules": [
"Authentication",
"Payments",
"Plans",
"Coupons",
"Coupon Validation",
"History",
"Security",
"Audit Logs"
]
}
],
"risks": [
{
"id": "RISK-BE-01",
"title": "Integração de pagamentos não definida",
"description": "O gateway de pagamento ainda não está definido, o que pode afetar esforço, custos, requisitos técnicos e validação de Cartão de Crédito, MB WAY e Apple Pay.",
"impact": "high",
"mitigation": "Selecionar gateway compatível com Portugal e validar SDKs, webhooks, Apple Pay e MB WAY antes da implementação final."
},
{
"id": "RISK-BE-02",
"title": "Fraude por reutilização de cupom",
"description": "Existe risco de o mesmo cupom ser apresentado mais de uma vez ou em restaurante diferente.",
"impact": "high",
"mitigation": "Usar códigos únicos, estado transacional do cupom, validação atómica no Backend e logs de tentativa de validação."
},
{
"id": "RISK-BE-03",
"title": "Ambiguidade sobre perfis de funcionário",
"description": "Os requisitos indicam validação por funcionário, mas não especificam claramente se haverá conta própria para funcionários, permissões por restaurante ou painel dedicado.",
"impact": "medium",
"mitigation": "Criar pergunta de clarificação sobre papéis de funcionário, administrador e cliente antes do fecho da arquitetura final."
},
{
"id": "RISK-BE-04",
"title": "Dados pessoais e conformidade",
"description": "O Backend irá guardar nome, e-mail, autenticação e histórico de utilização, exigindo cuidado com proteção de dados pessoais.",
"impact": "high",
"mitigation": "Aplicar autenticação segura, encriptação de segredos, minimização de dados, controlo de acesso e política clara de retenção."
},
{
"id": "RISK-BE-05",
"title": "Expiração de plano e cupom em condições de fronteira",
"description": "Podem ocorrer erros de validação em mudanças de dia, fuso horário, expiração de plano ou validação simultânea.",
"impact": "medium",
"mitigation": "Normalizar datas em UTC no Backend, aplicar validações transacionais e cobrir casos de fronteira com testes automatizados."
}
],
"artifacts": [
{
"type": "architecture",
"name": "Backend Architecture Pack - Undefined Capability",
"description": "Pacote de arquitetura Backend para a capability ainda não definida, cobrindo autenticação, pagamentos, planos, geração de cupons, validação de cupons, histórico, segurança, entidades de dados, endpoints e riscos técnicos.",
"stageId": "architecture"
}
]
}

