  "requirements": [
    {
      "id": "STK-01",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Criar conta e aceder à aplicação",
      "shall": "O cliente final precisa de criar conta e aceder à aplicação City Pass através de e-mail e palavra-passe para utilizar os benefícios disponíveis no MVP.",
      "status": "draft",
      "moduleTags": [
        "Frontend",
        "Backend",
        "Database"
      ],
      "parentId": "",
      "vLevel": 0
    },
    {
      "id": "STK-02",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Recuperar acesso à conta",
      "shall": "O cliente final precisa de conseguir recuperar o acesso à conta caso esqueça a palavra-passe.",
      "status": "draft",
      "moduleTags": [
        "Frontend",
        "Backend"
      ],
      "parentId": "",
      "vLevel": 0
    },
    {
      "id": "STK-03",
      "type": "functional",
      "title": "[Cliente][MVP] Visualizar experiência inicial premium",
      "shall": "O cliente final precisa de visualizar uma experiência inicial premium, com identidade visual City Pass, imagem turística ou gastronómica, proposta de valor clara e entrada simples na aplicação.",
      "status": "draft",
      "moduleTags": [
        "Frontend"
      ],
      "parentId": "STK-02",
      "vLevel": 1
    },
    {
      "id": "STK-04",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Consultar página inicial personalizada",
      "shall": "O cliente final precisa de consultar uma página inicial com saudação, pesquisa, categorias, parceiros em destaque e ofertas disponíveis para orientar o uso da aplicação.",
      "status": "draft",
      "moduleTags": [
        "Frontend",
        "Backend"
      ],
      "parentId": "",
      "vLevel": 0
    },
    {
      "id": "STK-05",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Consultar categorias disponíveis",
      "shall": "O cliente final precisa de consultar categorias como restaurantes, hotéis, tuk tuks, passeios, experiências e atrações para encontrar benefícios disponíveis na aplicação.",
      "status": "draft",
      "moduleTags": [
        "Frontend",
        "Backend",
        "Database"
      ],
      "parentId": "",
      "vLevel": 0
    },
    {
      "id": "STK-06",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Pesquisar parceiros e atrações",
      "shall": "O cliente final precisa de pesquisar parceiros, empresas, atrações, hotéis e experiências através de uma barra de pesquisa.",
      "status": "draft",
      "moduleTags": [
        "Frontend",
        "Backend",
        "Database"
      ],
      "parentId": "",
      "vLevel": 0
    },
    {
      "id": "STK-07",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Consultar parceiros disponíveis",
      "shall": "O cliente final precisa de consultar os parceiros disponíveis na aplicação, incluindo nome, imagem, categoria, desconto e informação resumida.",
      "status": "draft",
      "moduleTags": [
        "Frontend",
        "Backend",
        "Database"
      ],
      "parentId": "",
      "vLevel": 0
    },
    {
      "id": "STK-08",
      "type": "stakeholder",
      "title": "[Cliente][MVP] Consultar parceiros próximos ou em destaque",
