"method": "POST",
"path": "/auth/register",
"description": "Cria conta de cliente final com e-mail e palavra-passe."
},
{
"method": "POST",
"path": "/auth/login",
"description": "Autentica utilizador com e-mail e palavra-passe e devolve tokens de acesso."
},
{
"method": "POST",
"path": "/auth/social/google",
"description": "Autentica ou associa utilizador através de token Google, caso a autenticação social esteja configurada."
},
{
"method": "POST",
"path": "/auth/social/apple",
"description": "Autentica ou associa utilizador através de token Apple, caso a autenticação social esteja configurada."
},
