},
{
"method": "GET",
"path": "/auth/me",
"description": "Retorna dados básicos do utilizador autenticado, respetivos perfis e permissões."
},
{
"method": "POST",
"path": "/auth/password/forgot",
"description": "Inicia recuperação de palavra-passe por e-mail."
},
{
"method": "POST",
"path": "/auth/password/reset",
"description": "Redefine palavra-passe usando token temporário válido."
},
{
"method": "POST",
"path": "/partner/auth/login",
"description": "Autentica funcionário de parceiro para acesso ao City Pass Partner."
},
{
"method": "POST",
"path": "/admin/auth/login",
"description": "Autentica administrador para acesso ao painel administrativo."
},
{
"method": "GET",
"path": "/admin/users/{userId}/permissions",
"description": "Consulta permissões efetivas de um utilizador para uso administrativo."
},
{
"method": "PUT",
"path": "/admin/users/{userId}/roles",
"description": "Atualiza perfis atribuídos a um utilizador, restrito a administradores autorizados."
}
],
