{
“architectureObjects”: [
{
“name”: “Auth Backend Service”,
“type”: “service”,
“descriptionMarkdown”: “Serviço backend responsável por registo, login, autenticação social, recuperação de palavra-passe, emissão e validação de tokens, controlo de sessão e integração com permissões de acesso. Atende clientes finais, parceiros, funcionários e administradores.”
},
{
“name”: “Identity Provider Integration”,
“type”: “external_integration”,
“descriptionMarkdown”: “Camada de integração com provedores externos de autenticação social, inicialmente Google e Apple, condicionada à configuração ativa no projeto. Deve validar tokens externos, normalizar identidade do utilizador e associar ou criar conta interna quando aplicável.”
},
{
“name”: “Credential Authentication Flow”,
“type”: “flow”,
“descriptionMarkdown”: “Fluxo de autenticação por e-mail e palavra-passe. Inclui validação de credenciais, verificação de estado da conta, geração de access token, geração opcional de refresh token, registo de último acesso e resposta segura ao cliente.”
},
{
“name”: “Password Recovery Flow”,
“type”: “flow”,
“descriptionMarkdown”: “Fluxo para recuperação de palavra-passe através da opção Esqueceu sua senha. Inclui pedido de recuperação, geração de token temporário, envio de e-mail, validação do token e redefinição segura da palavra-passe.”
},
{
“name”: “Role Based Access Control”,
“type”: “security_component”,
“descriptionMarkdown”: “Componente de autorização baseado em perfis e permissões. Deve suportar clientes, parceiros, funcionários, administradores e visualizadores, garantindo que cada utilizador acede apenas às áreas e ações permitidas.”
},
{
“name”: “Session and Token Manager”,
“type”: “security_component”,
“descriptionMarkdown”: “Componente responsável por emitir, validar, renovar e revogar tokens de autenticação. Deve controlar expiração, rotação de refresh tokens, logout e invalidação de sessões comprometidas.”
},
{
“name”: “Personal Data Protection Layer”,
“type”: “security_component”,
“descriptionMarkdown”: “Camada transversal para proteção de dados pessoais de clientes, parceiros, funcionários e administradores. Inclui hashing de passwords, minimização de dados, registo de auditoria, controlo de acesso e práticas compatíveis com proteção de dados.”
},
{
“name”: “Administrative Access Boundary”,
“type”: “boundary”,
“descriptionMarkdown”: “Separação lógica entre autenticação de clientes, parceiros e administradores. O backend deve impedir escalonamento indevido de privilégios e garantir que endpoints administrativos exigem permissões específicas.”
}
],
